CREATE OR REPLACE FUNCTION ${database.defaultSchemaName}.ged_version_document_archive() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    doc uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.document_id ELSE NEW.document_id END;
BEGIN
    IF EXISTS (SELECT 1 FROM ${database.defaultSchemaName}.document d
                WHERE d.id = doc AND d.statut_conservation = 'ARCHIVE') THEN
        RAISE EXCEPTION 'Document % archivé : ses versions sont en lecture seule', doc
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$
